const options = {
    documentMode: 'document' as const,
    indentUnit: '    ',
    printWidth: 120,
    attributeLayout: 'auto' as const,
    preserveComments: true,
    preserveWhitespace: true,
};

const ast = parseHtml(html, options);
const output = printHtml(ast, options);

console.log('\n========== S19: FORMATTED HTML ==========\n');
console.log(output);
console.log('\n========== END S19 ==========\n');

// Idempotency test
const secondAst = parseHtml(output, options);
const secondOutput = printHtml(secondAst, options);

console.log(
    '[S19] Idempotency:',
    output === secondOutput ? 'Passed' : 'Failed'
);
